  "projects.oak-living-room.pl4.caption": { he: "חיפוי אלון בהיר מעל אדן אבן עם תאורה נסתרת.", en: "Light-oak paneling above a stone plinth with concealed lighting." },
  "projects.oak-living-room.pl4.alt": { he: "קיר מחופה אלון בהיר עם טלוויזיה, ומתחתיו אדן אבן עם פס אור נסתר ווילון שקוף. הדמיה.", en: "A light-oak paneled wall with a TV, above a stone plinth with a hidden line of light and a sheer curtain. Render." },
  "projects.oak-living-room.filmAlt": { he: "סרט קצר מתוך הדמיות הסלון: חיפוי העץ, המדפים ושולחן הקפה.", en: "A short film from the living-room visualizations: the paneling, the shelves and the coffee table." },
  "projects.oak-living-room.lightText": { he: "פס אור עדין מתחת לחיפוי העץ מפריד בינו לבין האבן, ונראה שהחיפוי מרחף מעל האדן.", en: "A soft line of light beneath the oak paneling separates it from the stone, so the paneling appears to hover above the plinth." },
